def transform(value, mapping):
    if isinstance(value, dict):
        return {k: transform(v, mapping) for k, v in value.items()}
    if isinstance(value, list):
        return [transform(v, mapping) for v in value]
    if isinstance(value, str):
        if value in KEEP:
            return value
        m = HSA_RE.match(value)
        if m:
            tmpl = HSA_MS if mapping is MS else HSA_ID
            return tmpl.format(name=m.group("name"))
        return mapping.get(value, value)
    return value


def looks_translatable(s: str) -> bool:
    """True when a string is human-readable prose (not a slug/url/key/id)."""
    t = s.strip()
    if not t:
        return False
    if re.fullmatch(r"[0-9.,%\- ]+", t):
        return False
    if t.startswith(("http", "/", "mailto:", "data:", "rgb(", "is-", "#", "©")):
        return False
    if t.startswith(("SGD ", "S$")):
        return False
    if "rgb(" in t and ";" in t:
        return False
    if re.search(r"%[0-9A-Fa-f]{2}", t):
        return False
    # lowercase slug / key / id tokens without spaces
    if re.fullmatch(r"[a-z0-9][a-z0-9\-_]*", t) and " " not in t and not any(c.isupper() for c in t):
        return False
    return True


def collect_missing(mapping, out):
    for dirpath, _dirnames, filenames in os.walk(ROOT):
        for fn in filenames:
            if not fn.endswith(".en.json"):
                continue
            data = json.load(open(os.path.join(dirpath, fn), encoding="utf-8"))
            _walk_strings(data, mapping, out)


def _walk_strings(value, mapping, out):
    if isinstance(value, dict):
        for v in value.values():
            _walk_strings(v, mapping, out)
    elif isinstance(value, list):
        for v in value:
            _walk_strings(v, mapping, out)
    elif isinstance(value, str):
        if value in KEEP or value in mapping or HSA_RE.match(value):
            return
        if looks_translatable(value):
            out.add(value)


def main():
    files = []
    for dirpath, _dirnames, filenames in os.walk(ROOT):
        for fn in filenames:
            if fn.endswith(".en.json"):
                files.append(os.path.join(dirpath, fn))
    files.sort()

    missing_ms = []
    missing_id = []
    for path in files:
        data = json.load(open(path, encoding="utf-8"))
        for lang, mapping, missing, suffix in (
            ("ms", MS, missing_ms, ".ms.json"),
            ("id", ID, missing_id, ".id.json"),
        ):
            out = transform(data, mapping)
            out_path = path[: -len(".en.json")] + suffix
            with open(out_path, "w", encoding="utf-8") as fh:
                json.dump(out, fh, ensure_ascii=False, indent=2)
                fh.write("\n")

    print(f"Generated {len(files) * 2} files.")
    for lang, mapping in (("MS", MS), ("ID", ID)):
        missing = set()
        collect_missing(mapping, missing)
        print(f"[{lang}] untranslated translatable strings: {len(missing)}")
        for s in sorted(missing):
            print(f"    {s!r}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
